(()=>{const verse=document.querySelector('.hero-verse'),research=document.querySelector('.research-by'),grid=document.querySelector('.research-grid');if(!verse||!research)return;const wrap=document.createElement('div');wrap.className='bottom-bible-verse';wrap.appendChild(verse);if(grid&&grid.parentNode)grid.parentNode.insertBefore(wrap,grid.nextSibling);else research.appendChild(wrap);const style=document.createElement('style');style.textContent='.hero .hero-verse{position:static!important}.bottom-bible-verse{max-width:900px;margin:42px auto 0;padding:0 20px;text-align:center}.bottom-bible-verse .hero-verse{position:static!important;display:block!important;max-width:900px!important;margin:0 auto!important;padding:22px 28px!important;text-align:center!important;color:#0752ad!important;font-size:clamp(18px,2.4vw,25px)!important;font-weight:900!important;line-height:1.5!important;text-shadow:none!important;border:1px solid rgba(255,255,255,.9)!important;border-radius:20px!important;background:linear-gradient(135deg,rgba(255,255,255,.72),rgba(220,244,255,.38))!important;box-shadow:0 18px 48px rgba(0,72,145,.16),inset 0 1px 0 rgba(255,255,255,.95)!important;backdrop-filter:blur(18px) saturate(145%)!important;-webkit-backdrop-filter:blur(18px) saturate(145%)!important}@media(max-width:760px){.bottom-bible-verse{margin-top:28px;padding:0}.bottom-bible-verse .hero-verse{padding:18px!important;font-size:17px!important}}';document.head.appendChild(style)})();